css:
.dd-page { background: #ffffff; color: #14171c;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    font-weight: 400; -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility; overflow-x: hidden; }
.key { font-style: normal; color: #a72632; }
.top { position: absolute; top: 0; left: 0; right: 0; z-index: 60;
    display: flex; align-items: center; justify-content: space-between; padding: 20px 40px;
    background: transparent; transition: background .3s cubic-bezier(0.16,1,0.3,1), box-shadow .3s cubic-bezier(0.16,1,0.3,1), border-color .3s cubic-bezier(0.16,1,0.3,1), padding .3s cubic-bezier(0.16,1,0.3,1);
    border-bottom: 1px solid transparent; }
.top.solid { position: fixed; padding: 14px 40px; background: #fff;
    border-bottom: 1px solid rgba(20,23,28,0.12); box-shadow: 0 6px 24px -14px rgba(20, 23, 28, 0.35); }
.nav-brand { display: flex; align-items: center; text-decoration: none; white-space: nowrap; line-height: 1; }
.f-nav-brand-img { height: 34px; width: auto; display: block; }
.f-nav-brand-logo-white { display: block; }
.f-nav-brand-logo-color { display: none; }
.nav-cta { display: inline-flex; align-items: center; gap: 8px;
    background: #a72632; color: #fff; padding: 11px 20px; border-radius: 4px;
    font-weight: 700; font-size: 10.5px; letter-spacing: 0.16em; text-transform: uppercase; text-decoration: none;
    border: 2px solid #a72632; font-family: inherit; cursor: pointer; -webkit-appearance: none; appearance: none;
    transition: background .2s, color .2s, opacity .35s cubic-bezier(0.16,1,0.3,1), transform .35s cubic-bezier(0.16,1,0.3,1); }
.nav-cta:hover { background: transparent; color: #a72632; }
.nav-cta:focus { outline: 2px solid #cf3a45; outline-offset: 4px; }
.f-nav-cta-arrow { transition: transform .2s cubic-bezier(0.16,1,0.3,1); }
.wv-cap { text-align: center; font-size: 13.5px; color: rgba(255,255,255,0.74); margin-top: 20px; letter-spacing: 0.02em; text-shadow: 0 1px 16px rgba(0,0,0,0.5); }
@media screen and (max-width: 767px) { .top { padding: 12px 22px; } .top.solid { padding: 12px 22px; } .f-nav-brand-img { height: 30px; } .nav-cta { padding: 10px 16px; font-size: 10px; } }

.sec { position: relative; scroll-margin-top: 96px; }
.container { max-width: 991px; margin: 0 auto; padding: 0 48px; }
.hd { font-weight: 900; letter-spacing: -0.03em; line-height: 1.0; }
.hero-confirm { position: relative; min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 100px 0 84px; text-align: center; overflow: hidden; background: #f3f5f8; }
.hero-bg { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: center; filter: blur(20px) brightness(1.02) saturate(1.14); transform: scale(1.16); z-index: 0; }
.f-hero-confirm-af { position: absolute; inset: 0; z-index: 1; pointer-events: none;
    background:
      radial-gradient(ellipse 76% 48% at 50% 32%, rgba(20,10,12,0.32), transparent 70%),
      linear-gradient(180deg, rgba(20,10,12,0.28) 0%, rgba(20,10,12,0.03) 24%, rgba(20,10,12,0.02) 56%, rgba(20,10,12,0.30) 100%); }
.f-hero-confirm-container { position: relative; z-index: 2; width: 100%; max-width: 991px; }
.f-hero-confirm-h1 { color: #fff; font-size: clamp(44px, 6.6vw, 100px); text-transform: uppercase; margin: 0; text-wrap: balance; text-shadow: 0 2px 44px rgba(0,0,0,0.45); }
.f-hero-confirm-h1-dot { color: #cf3a45; }
.f-hero-confirm-lead { font-size: clamp(17px, 1.5vw, 21px); line-height: 1.6; color: rgba(255,255,255,0.94); max-width: 767px; margin: 22px auto 0; text-shadow: 0 1px 22px rgba(0,0,0,0.5); }
.f-hero-confirm-lead-b { color: #fff; font-weight: 700; }
.video-frame { position: relative; z-index: 2; max-width: 991px; width: 100%; margin: 42px auto 0; border-radius: 4px; overflow: hidden;
    aspect-ratio: 16 / 9; background: #0c0e12; cursor: pointer;
    box-shadow: 0 0 0 3px #fff, 0 30px 74px -34px rgba(0,0,0,0.5); }
.f-video-frame-img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: center 22%; display: block; filter: brightness(1.08) saturate(1.06); }
.f-video-frame-af { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(11,17,32,0) 54%, rgba(8,10,16,0.34) 100%); transition: opacity .25s; }
.f-video-frame-hover-af { opacity: 0.9; }
.f-video-frame-vf-play { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); z-index: 2;
    width: 88px; height: 88px; border-radius: 50%; background: #a72632;
    display: flex; align-items: center; justify-content: center;
    box-shadow: 0 16px 40px -10px rgba(167,38,50, 0.72); }
.f-video-frame-vf-play-af { position: absolute; inset: 0; border-radius: 50%;
    box-shadow: 0 0 0 0 rgba(167,38,50, 0.55); }
.f-video-frame-vf-play-svg { width: 30px; height: 30px; fill: #fff; margin-left: 4px; }
.f-video-frame-vf-chip { position: absolute; left: 18px; bottom: 18px; z-index: 2;
    font-weight: 800; font-size: 10.5px; letter-spacing: 0.14em; text-transform: uppercase; color: #fff;
    padding: 8px 13px; border-radius: 4px; border: 1px solid rgba(255,255,255,0.7);
    background: rgba(10,14,24,0.35); backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); }
.hero-cue { display: inline-flex; flex-direction: column; align-items: center; gap: 10px; margin: 38px auto 0; text-decoration: none; text-align: center; }
.hero-cue-text { font-weight: 800; font-size: 12px; letter-spacing: 0.13em; text-transform: uppercase; color: #fff; max-width: 479px; line-height: 1.5;
    text-shadow: 0 1px 2px rgba(0,0,0,0.75), 0 2px 16px rgba(0,0,0,0.62), 0 0 30px rgba(0,0,0,0.45); }
.f-hero-cue-text-b { color: #fff; font-weight: 800; }
.hero-cue-arrow { width: 44px; height: 44px; border-radius: 50%; border: 1.5px solid rgba(255,255,255,0.85); background: rgba(10,8,12,0.42); backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); box-shadow: 0 8px 22px -8px rgba(0,0,0,0.6); display: flex; align-items: center; justify-content: center;  transition: border-color .2s, background .2s; }
.f-hero-cue-arrow-svg { width: 20px; height: 20px; stroke: #fff; stroke-width: 2.4; fill: none; stroke-linecap: round; stroke-linejoin: round; }
@media screen and (max-width: 767px) { .container { padding: 0 22px; } .hero-confirm { justify-content: flex-start; min-height: 90vh; padding: 100px 0 64px; } .video-frame { margin-top: 28px; box-shadow: 0 0 0 2px #fff, 0 24px 56px -28px rgba(0,0,0,0.5); } .f-video-frame-vf-play { width: 68px; height: 68px; } .f-video-frame-vf-play-svg { width: 24px; height: 24px; } .hero-cue { margin-top: 28px; } .hero-cue-text { font-size: 11px; } }

.eyebrow { font-weight: 700; font-size: 12px; letter-spacing: 0.32em;
    text-transform: uppercase; color: #616a78;
    display: inline-flex; align-items: center; gap: 16px; }
.f-eyebrow-pip { width: 34px; height: 3px; background: #a72632; display: inline-block; }
.eyebrow.accent { color: #a72632; }
.eyebrow.on-dark { color: rgba(255,255,255,0.82); }
.eyebrow.center { justify-content: center; }
.reveal { transition: opacity .8s cubic-bezier(0.16,1,0.3,1), transform .8s cubic-bezier(0.16,1,0.3,1); }
.reveal.in { opacity: 1; transform: none; }
.f-stagger { transition: opacity .7s cubic-bezier(0.16,1,0.3,1), transform .7s cubic-bezier(0.16,1,0.3,1); }
.next { position: relative; overflow: hidden; padding: 124px 0; background: #f3f5f8; }
.f-next-container { position: relative; z-index: 1; }
.next-head { text-align: center; max-width: 991px; margin: 0 auto 66px; }
.f-next-head-eyebrow { justify-content: center; }
.f-next-head-h2 { color: #14171c; font-size: clamp(32px, 4.2vw, 60px); text-transform: uppercase; margin-top: 20px; text-wrap: balance; }
.f-next-head-h2-em { font-style: normal; color: #a72632; }
.steps { position: relative; display: grid; grid-template-columns: repeat(3, 1fr); gap: clamp(30px, 5vw, 64px); max-width: 991px; margin: 0 auto; padding-top: 46px; }
.steps-rail { position: absolute; top: 6px; left: 7%; right: 7%; height: 3px; border-radius: 3px; background: rgba(167,38,50,0.16); overflow: hidden; }
.f-steps-rail-af { position: absolute; inset: 0; width: 0; background: #a72632; transition: width 1.4s cubic-bezier(0.16,1,0.3,1); }
.step { position: relative; text-align: center; }
.f-step-bf { position: absolute; top: -40px; left: 50%; transform: translateX(-50%); width: 14px; height: 14px; border-radius: 50%; background: #f3f5f8; border: 3px solid rgba(167,38,50,0.3); z-index: 2; transition: border-color .4s ease, background .4s ease, box-shadow .4s ease; }
.step-num { font-weight: 900; font-size: clamp(80px, 9vw, 132px); line-height: 0.85; letter-spacing: -0.05em; font-variant-numeric: tabular-nums; color: transparent; -webkit-text-stroke: 2px rgba(167,38,50, 0.5); }
.f-step-h3 { color: #14171c; font-size: clamp(20px, 1.9vw, 26px); text-transform: uppercase; letter-spacing: -0.02em; margin: 16px 0 12px; }
.f-step-p { font-size: 15.5px; line-height: 1.62; color: #545c68; max-width: 479px; margin: 0 auto; }
.f-step-p-b { color: #14171c; font-weight: 700; }
.whitelist-note { position: relative; max-width: 767px; margin: 76px auto 0; padding: 50px 44px 42px; border-radius: 16px;
    text-align: center; background: #fff; border: 1px solid rgba(20,23,28,0.12);
    box-shadow: 0 30px 62px -30px rgba(20,23,28,0.42); }
.f-whitelist-note-wn-badge { position: absolute; top: 0; left: 50%; transform: translate(-50%, -50%);
    display: inline-flex; align-items: center; font-weight: 800; font-size: 13px; letter-spacing: 0.14em;
    text-transform: uppercase; color: #fff; background: #a72632; padding: 10px 22px; border-radius: 100px;
    box-shadow: 0 14px 28px -8px rgba(167,38,50,0.55); white-space: nowrap; }
.f-whitelist-note-h4 { font-size: clamp(22px, 2.4vw, 30px); font-weight: 900; letter-spacing: -0.02em; text-transform: uppercase; color: #14171c; margin: 6px 0 16px; }
.f-whitelist-note-p { font-size: 15px; line-height: 1.62; color: #545c68; max-width: 479px; margin: 0 auto; }
.f-whitelist-note-p-p { margin-top: 10px; }
.f-whitelist-note-b { color: #14171c; font-weight: 700; }
.f-whitelist-note-wn-help { margin-top: 24px; font-size: 13.5px; color: #616a78; }
.f-whitelist-note-wn-help-a { color: #a72632; font-weight: 700; text-decoration: none; border-bottom: 2px solid rgba(167,38,50,0.4); padding-bottom: 1px; transition: border-color .2s; }
.f-whitelist-note-wn-help-a-hover:hover { border-bottom-color: #a72632; }
@media screen and (max-width: 991px) { .next { padding: 88px 0; } .steps { grid-template-columns: 1fr; gap: 46px; max-width: 479px; padding-top: 8px; } .steps-rail, .f-step-bf { display: none; } }
@media screen and (max-width: 479px) { .whitelist-note { padding: 46px 24px 34px; } }

.sessions { background: #ffffff; padding: 120px 0; }
.ep-head { text-align: center; max-width: 767px; margin: 0 auto; }
.f-ep-head-eyebrow { justify-content: center; }
.f-ep-head-h2 { font-size: clamp(32px, 4vw, 58px); text-transform: uppercase; margin-top: 20px; text-wrap: balance; }
.f-ep-head-h2-em { font-style: normal; color: #a72632; }
.ep-expiry { display: inline-flex; align-items: center; gap: 10px; margin-top: 24px; padding: 11px 20px; border-radius: 100px;
    background: rgba(167,38,50, 0.07); border: 1px solid rgba(167,38,50, 0.28); color: #a72632;
    font-weight: 700; font-size: 13.5px; letter-spacing: 0.01em; }
.f-ep-expiry-svg { width: 16px; height: 16px; stroke: #a72632; stroke-width: 2; fill: none; flex-shrink: 0; }
.ep-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 26px; margin: 54px auto 0; max-width: 991px; }
.ep-card { position: relative; display: block; border-radius: 8px; overflow: hidden; border: 1px solid rgba(20,23,28,0.12);
    box-shadow: 0 12px 36px -16px rgba(20,23,28,0.32); transition: transform .28s cubic-bezier(0.16,1,0.3,1), box-shadow .28s cubic-bezier(0.16,1,0.3,1); }
.ep-card:hover { transform: translateY(-6px); box-shadow: 0 40px 70px -30px rgba(20,23,28,0.48); }
.f-ep-card-img { display: block; width: 100%; height: auto; }
.ep-metarow { position: absolute; top: 12px; right: 12px; z-index: 2; display: flex; gap: 8px; }
.ep-meta { display: inline-flex; align-items: center; gap: 6px;
    font-weight: 700; font-size: 11px; letter-spacing: 0.09em; text-transform: uppercase; color: #fff;
    background: rgba(10,8,10,0.5); border: 1px solid rgba(255,255,255,0.22); border-radius: 100px;
    padding: 6px 12px; backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); }
@media screen and (max-width: 767px) { .sessions { padding: 84px 0; } .ep-grid { grid-template-columns: 1fr; max-width: 479px; } }

.tw-proof { display: flex; flex-direction: column; align-items: center; gap: 15px; margin-top: 30px; }
.f-tw-proof-proof-stars { color: #ffce3a; font-size: 16px; letter-spacing: 3px; line-height: 1; }
.f-tw-proof-proof-line { font-size: 16.5px; line-height: 1.55; color: #545c68; max-width: 479px; margin: 0; }
.f-tw-proof-proof-line-b { color: #14171c; font-weight: 700; }
.tw { background: #f3f5f8; padding: 128px 0; overflow: hidden; }
.f-tw-bf { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse 60% 40% at 50% 0%, rgba(167,38,50, 0.07), transparent 62%); }
.f-tw-container { position: relative; z-index: 1; }
.tw-head { text-align: center; max-width: 767px; margin: 0 auto 56px; }
.f-tw-head-eyebrow { justify-content: center; }
.f-tw-head-h2 { color: #14171c; font-size: clamp(34px, 4.4vw, 66px); text-transform: uppercase; margin-top: 22px; text-wrap: balance; }
.f-tw-head-h2-em { font-style: normal; color: #a72632; }
.f-tw-head-p { color: #545c68; font-size: clamp(16px, 1.3vw, 19px); line-height: 1.55; margin-top: 22px; }
.pgallery { position: relative; display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-top: 52px; }
.pcol { display: flex; flex-direction: column; gap: 18px; will-change: transform; }
.ptile { position: relative; aspect-ratio: 1 / 1; border-radius: 10px; overflow: hidden; background: #1c0a0e; border: 1px solid rgba(255,255,255,0.10); box-shadow: 0 20px 46px -28px rgba(20,23,28,0.42); transition: transform .3s cubic-bezier(0.16,1,0.3,1), box-shadow .3s cubic-bezier(0.16,1,0.3,1), border-color .3s; }
.f-ptile-img { width: 100%; height: 100%; object-fit: cover; object-position: center 14%; display: block; }
.f-ptile-af { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, rgba(6,8,12,0) 38%, rgba(6,8,12,0.5) 64%, rgba(6,8,12,0.92) 100%); }
.ptile:hover { transform: translateY(-5px); border-color: rgba(167,38,50,0.5); box-shadow: 0 34px 64px -30px rgba(167,38,50,0.42); }
.ptile-chip { position: absolute; top: 12px; right: 12px; z-index: 2; font-weight: 800; font-size: 9.5px; letter-spacing: 0.12em; text-transform: uppercase; color: #fff; padding: 5px 10px; border-radius: 4px; border: 1px solid rgba(255,255,255,0.7); background: rgba(10,14,24,0.35); backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); }
.ptile-info { position: absolute; left: 0; right: 0; bottom: 0; z-index: 2; padding: 16px 18px 18px; }
.ptile-stars { color: #ffce3a; font-size: 12px; letter-spacing: 2.5px; line-height: 1; margin-bottom: 8px; }
.ptile-quote { font-size: 15.5px; font-weight: 800; color: #fff; line-height: 1.2; letter-spacing: -0.01em; margin: 0 0 9px; }
.ptile-name { font-weight: 800; font-size: 15px; color: #fff; line-height: 1.16; letter-spacing: 0.01em; }
.f-ptile-name-span { display: block; font-weight: 600; font-size: 10.5px; letter-spacing: 0.06em; text-transform: uppercase; color: #cbd2de; margin-top: 4px; }
@media screen and (max-width: 991px) { .tw { padding: 84px 0; } .pgallery { grid-template-columns: 1fr 1fr; gap: 14px; } .pcol { display: contents; } .f-pgallery-pcol { margin-top: 0; } .ptile { aspect-ratio: auto; display: flex; flex-direction: column; } .f-ptile-img { aspect-ratio: 1 / 1; height: auto; } .f-ptile-af { display: none; } .ptile-info { position: static; background: #06080c; padding: 14px 14px 16px; } }

.f-eyebrow-on-dark-pip { background: #cf3a45; }
.btn { display: inline-flex; align-items: center; gap: 12px;
    font-weight: 800; font-size: 12.5px; letter-spacing: 0.2em; text-transform: uppercase;
    padding: 20px 38px; border-radius: 4px; text-decoration: none; cursor: pointer;
    background: #a72632; color: #fff; border: 2px solid #a72632;
    transition: background .2s cubic-bezier(0.16,1,0.3,1), color .2s, transform .2s, box-shadow .2s;
    box-shadow: 0 14px 30px -12px rgba(167,38,50, 0.5);
    position: relative; overflow: hidden; }
.btn:hover { background: #fff; color: #a72632; transform: translateY(-2px); box-shadow: 0 18px 36px -14px rgba(167,38,50, 0.4); }
.btn.ondark { background: #cf3a45; border-color: #cf3a45; }
.btn.ondark:hover { background: #fff; color: #a72632; border-color: #fff; box-shadow: 0 18px 36px -14px rgba(0,0,0,0.5); }
.f-btn-arrow { transition: transform .2s cubic-bezier(0.16,1,0.3,1); }
.btn-line { display: inline-flex; align-items: center; gap: 9px;
    font-weight: 700; font-size: 11.5px; letter-spacing: 0.18em; text-transform: uppercase;
    text-decoration: none; color: #14171c; cursor: pointer;
    border-bottom: 2px solid #a72632; padding-bottom: 4px; transition: color .2s; }
.btn-line:hover { color: #a72632; }
.btn-line.ondark { color: #fff; border-bottom-color: #cf3a45; }
.btn-line.ondark:hover { color: #cf3a45; }
.f-btn-line-arrow { transition: transform .2s cubic-bezier(0.16,1,0.3,1); }
.close-band { color: #fff; padding: 116px 0; text-align: center; overflow: hidden;
    background: radial-gradient(ellipse 70% 55% at 50% 0%, rgba(167,38,50, 0.30), transparent 62%), linear-gradient(160deg, #2a1015 0%, #1c0a0e 100%); }
.f-close-band-container { position: relative; z-index: 1; }
.f-close-band-eyebrow { justify-content: center; }
.f-close-band-h2 { color: #fff; font-size: clamp(40px, 6vw, 90px); text-transform: uppercase; margin: 20px 0 0; text-wrap: balance; }
.f-close-band-h2-em { font-style: normal; color: #cf3a45; }
.f-close-band-p { font-size: clamp(16px, 1.4vw, 20px); line-height: 1.6; color: #e7d4d6; max-width: 767px; margin: 26px auto 0; }
.close-actions { display: flex; align-items: center; justify-content: center; gap: 30px; flex-wrap: wrap; margin-top: 40px; }
@media screen and (max-width: 767px) { .close-band { padding: 84px 0; } }

.site-footer { background: #0a0a0a; color: #c3bbb9; padding: 70px 0 40px; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1.2fr; gap: 40px; }
.f-foot-brand-fb-logo { height: 46px; width: auto; display: block; }
.f-foot-brand-tag { font-size: 14px; line-height: 1.6; color: #fff; margin-top: 20px; max-width: 479px; }
.socials { display: flex; gap: 12px; margin-top: 22px; }
.f-socials-a { width: 34px; height: 34px; border: 1px solid rgba(255,255,255,0.16); border-radius: 4px; display: flex; align-items: center; justify-content: center; transition: background .2s, border-color .2s; }
.f-socials-a-hover:hover { background: #a72632; border-color: #a72632; }
.f-socials-svg { width: 15px; height: 15px; fill: #c3bbb9; }
.f-footer-col-h3 { font-size: 10px; letter-spacing: 0.32em; text-transform: uppercase; color: #988f8d; font-weight: 600; margin-bottom: 24px; }
.f-footer-col-ul { list-style: none; }
.f-footer-col-li { margin-bottom: 14px; font-size: 12px; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; }
.f-footer-col-a { color: #c3bbb9; text-decoration: none; transition: color .18s; }
.f-footer-col-a-hover:hover { color: #fff; }
.bmc-corner { display: flex; align-items: flex-start; gap: 16px; color: #a89f9d; text-decoration: none; transition: color .2s; }
.bmc-corner:hover { color: #fff; }
.f-bmc-corner-img { width: 52px; height: 52px; display: block; filter: brightness(0) invert(1) opacity(0.85); transition: opacity .2s; flex-shrink: 0; margin-top: 2px; }
.bmc-corner-text { display: flex; flex-direction: column; gap: 8px; }
.bmc-corner-title { font-weight: 700; font-size: 11px; letter-spacing: 0.24em; text-transform: uppercase; color: #a89f9d; line-height: 1; }
.bmc-corner-tag { font-weight: 700; font-size: 14px; letter-spacing: 0.02em; text-transform: uppercase; color: #fff; line-height: 1.2; }
.bmc-corner-cta { font-weight: 500; font-size: 10px; letter-spacing: 0.22em; text-transform: uppercase; color: #a89f9d; display: inline-flex; align-items: center; gap: 6px; margin-top: 2px; transition: color .2s; }
.footer-bottom { display: flex; justify-content: space-between; align-items: center; gap: 20px; flex-wrap: wrap; margin-top: 52px; padding-top: 26px; border-top: 1px solid rgba(255,255,255,0.12); font-size: 10px; font-weight: 400; letter-spacing: 0.16em; text-transform: uppercase; color: #867d7b; }
.f-footer-bottom-legal-links { display: flex; gap: 24px; }
.f-footer-bottom-a { color: #867d7b; text-decoration: none; }
.f-footer-bottom-a-hover:hover { color: #c3bbb9; }
@media screen and (max-width: 991px) { .footer-grid { grid-template-columns: 1fr 1fr; gap: 34px; } .foot-brand { grid-column: 1 / -1; } }
@media screen and (max-width: 479px) { .footer-grid { grid-template-columns: 1fr; } }

.toast { position: fixed; left: 50%; bottom: 28px; transform: translateX(-50%) translateY(20px);
    background: #14171c; color: #fff; padding: 14px 22px; border-radius: 4px;
    font-weight: 700; font-size: 13px; letter-spacing: 0.03em;
    box-shadow: 0 18px 40px -14px rgba(0,0,0,0.5);
    opacity: 0; pointer-events: none; transition: opacity .25s cubic-bezier(0.16,1,0.3,1), transform .25s cubic-bezier(0.16,1,0.3,1); z-index: 300; }
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

.xp-modal { position: fixed; inset: 0; z-index: 500; display: flex; align-items: center; justify-content: center; padding: 24px;
    background: rgba(6,6,6,0.62); backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px);
    opacity: 0; visibility: hidden; transition: opacity .28s cubic-bezier(0.16,1,0.3,1), visibility .28s cubic-bezier(0.16,1,0.3,1); }
.xp-modal.open { opacity: 1; visibility: visible; }
.xp-card { position: relative; width: 100%; max-width: 479px; background: #fff; border-radius: 0; padding: 38px 34px 30px;
    box-shadow: 0 40px 100px -28px rgba(0,0,0,0.55); transform: translateY(16px); transition: transform .3s cubic-bezier(0.16,1,0.3,1);
    max-height: calc(100vh - 48px); overflow-y: auto; text-align: left; }
.xp-close { position: absolute; top: 16px; right: 16px; width: 38px; height: 38px; border-radius: 50%; border: 1px solid rgba(20,23,28,0.12);
    background: #fff; color: #616a78; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: background .2s, color .2s; }
.xp-close:hover { background: #f3f5f8; color: #14171c; }
.f-xp-close-svg { width: 15px; height: 15px; stroke: currentColor; stroke-width: 1.8; fill: none; stroke-linecap: round; }
.xp-accent { display: block; width: 52px; height: 3px; background: #a72632; border-radius: 2px; margin-bottom: 15px; }
.xp-eyebrow { font-weight: 800; font-size: 11px; letter-spacing: 0.24em; text-transform: uppercase; color: #a72632; margin-bottom: 12px; }
.xp-title { font-weight: 900; letter-spacing: -0.03em; line-height: 1.04; font-size: clamp(23px, 3vw, 29px); text-transform: uppercase; color: #14171c; }
.f-xp-title-em { font-style: normal; color: #a72632; }
.xp-sub { font-size: 14px; line-height: 1.55; color: #545c68; margin: 12px 0 20px; }
.xp-list { display: block; }
.xp-session { position: relative; display: block; border-radius: 0; overflow: hidden; border: 1px solid rgba(20,23,28,0.12);
    box-shadow: 0 12px 30px -16px rgba(20,23,28,0.32); transition: transform .25s cubic-bezier(0.16,1,0.3,1), box-shadow .25s cubic-bezier(0.16,1,0.3,1); text-decoration: none; }
.xp-session[hidden] { display: none; }
.xp-session:hover { transform: translateY(-4px); box-shadow: 0 26px 50px -24px rgba(20,23,28,0.46); }
.f-xp-session-img { display: block; width: 100%; height: auto; }
.xp-session-date { position: absolute; top: 10px; right: 10px; z-index: 2; display: inline-flex; align-items: center; gap: 6px;
    font-weight: 700; font-size: 11px; letter-spacing: 0.09em; text-transform: uppercase; color: #fff;
    background: rgba(10,8,10,0.5); border: 1px solid rgba(255,255,255,0.22); border-radius: 100px; padding: 6px 12px;
    backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); }
@media screen and (max-width: 479px) { .xp-card { padding: 34px 22px 26px; } }
